// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "OpenZeppelin/openzeppelin-contracts/contracts/access/AccessControl.sol";
import "OpenZeppelin/openzeppelin-contracts/contracts/security/ReentrancyGuard.sol";
import "OpenZeppelin/openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import "OpenZeppelin/openzeppelin-contracts/contracts/ownership/Ownable.sol";

/**
 * @title Dropshipping Contract
 * @author [Your Name]
 * @notice This contract manages dropshipping operations between a private limited company and its customers.
 * @dev This contract implements product management, order processing, payment handling, and inventory management.
 */
contract Dropshipping is AccessControl, ReentrancyGuard, Ownable {
    // Roles
    bytes32 public constant ADMIN = "ADMIN";
    bytes32 public constant COMPANY = "COMPANY";
    bytes32 public constant CUSTOMER = "CUSTOMER";

    // Mapping of products by SKU
    mapping(string => Product) public products;
    string[] public allSKUs;

    // Mapping of orders by order ID
    mapping(bytes32 => Order) public orders;
    bytes32[] public allOrderIds;

    // Mapping of payments by payment ID
    mapping(bytes32 => Payment) public payments;
    bytes32[] public allPaymentIds;

    // ERC20 token for payments
    IERC20 public token;

    // Inventory management
    mapping(string => uint256) public inventory;

    // Events
    event ProductAdded(string indexed sku, string name, uint256 price);
    event ProductUpdated(string indexed sku, string name, uint256 price);
    event OrderPlaced(bytes32 indexed orderId, string sku, address customer, uint256 quantity);
    event OrderStatusUpdated(bytes32 indexed orderId, OrderStatus status);
    event OrderCanceled(bytes32 indexed orderId);
    event PaymentReceived(bytes32 indexed paymentId, uint256 amount);
    event PaymentRefunded(bytes32 indexed paymentId, uint256 amount);
    event StockUpdated(string indexed sku, uint256 quantity);

    // Enum for order status
    enum OrderStatus { PENDING, SHIPPED, DELIVERED, CANCELED }

    // Struct for products
    struct Product {
        string name;
        uint256 price;
        uint256 stock;
        bool active;
    }

    // Struct for orders
    struct Order {
        string sku;
        address customer;
        uint256 quantity;
        OrderStatus status;
        uint256 createdAt;
        uint256 updatedAt;
    }

    // Struct for payments
    struct Payment {
        bytes32 orderId;
        uint256 amount;
        uint256 timestamp;
    }

    /**
     * @notice Initializes the contract with ERC20 token and roles setup
     * @param _tokenAddress The address of the ERC20 token for payments
     * @dev The owner of the contract will be the COMPANY role
     */
    constructor(address _tokenAddress) Ownable() {
        token = IERC20(_tokenAddress);
        _grantRole(ADMIN, msg.sender);
        _grantRole(COMPANY, msg.sender);
    }

    /**
     * @notice Adds a new product to the catalog
     * @param _sku The unique SKU of the product
     * @param _name The name of the product
     * @param _price The price of the product in wei
     * @param _stock The initial stock quantity
     * @dev Only COMPANY role can call this function
     */
    function addProduct(string memory _sku, string memory _name, uint256 _price, uint256 _stock) public onlyRole(COMPANY) {
        require(bytes(_sku).length > 0, "SKU cannot be empty");
        require(_price > 0, "Price must be greater than zero");
        require(_stock > 0, "Stock must be greater than zero");

        Product memory product = Product(_name, _price, _stock, true);
        products[_sku] = product;
        allSKUs.push(_sku);
        inventory[_sku] = _stock;

        emit ProductAdded(_sku, _name, _price);
    }

    /**
     * @notice Updates an existing product in the catalog
     * @param _sku The SKU of the product to update
     * @param _name The new name of the product
     * @param _price The new price of the product in wei
     * @param _stock The new stock quantity
     * @dev Only COMPANY role can call this function
     */
    function updateProduct(string memory _sku, string memory _name, uint256 _price, uint256 _stock) public onlyRole(COMPANY) {
        require(bytes(_sku).length > 0, "SKU cannot be empty");
        require(_price > 0, "Price must be greater than zero");
        require(_stock >= 0, "Stock cannot be negative");

        Product storage product = products[_sku];
        require(product.stock > 0, "Product not found");

        if (bytes(_name).length > 0) {
            product.name = _name;
        }
        if (_price > 0) {
            product.price = _price;
        }
        if (_stock > 0) {
            product.stock = _stock;
            inventory[_sku] = _stock;
            emit StockUpdated(_sku, _stock);
        }

        emit ProductUpdated(_sku, product.name, product.price);
    }

    /**
     * @notice Places a new order
     * @param _sku The SKU of the product being ordered
     * @param _quantity The number of items to order
     * @dev Only CUSTOMER role can call this function
     */
    function placeOrder(string memory _sku, uint256 _quantity) public onlyRole(CUSTOMER) {
        require(bytes(_sku).length > 0, "SKU cannot be empty");
        require(_quantity > 0, "Quantity must be greater than zero");

        Product memory product = products[_sku];
        require(product.stock > 0, "Product out of stock");
        require(product.stock >= _quantity, "Not enough stock available");
        require(product.price > 0, "Product price not set");

        bytes32 orderId = keccak256(abi.encodePacked(block.timestamp, msg.sender, _sku));
        orders[orderId] = Order(_sku, msg.sender, _quantity, OrderStatus.PENDING, block.timestamp, block.timestamp);
        allOrderIds.push(orderId);

        // Deduct stock
        product.stock -= _quantity;
        products[_sku] = product;
        inventory[_sku] -= _quantity;
        emit StockUpdated(_sku, inventory[_sku]);

        emit OrderPlaced(orderId, _sku, msg.sender, _quantity);
    }

    /**
     * @notice Updates the status of an order
     * @param _orderId The unique ID of the order
     * @param _status The new status of the order
     * @dev Only COMPANY role can call this function
     */
    function updateOrderStatus(bytes32 _orderId, OrderStatus _status) public onlyRole(COMPANY) {
        Order storage order = orders[_orderId];
        require(order.createdAt > 0, "Order not found");

        order.status = _status;
        order.updatedAt = block.timestamp;

        emit OrderStatusUpdated(_orderId, _status);
    }

    /**
     * @notice Cancels an order
     * @param _orderId The unique ID of the order
     * @dev Only CUSTOMER role can call this function
     */
    function cancelOrder(bytes32 _orderId) public onlyRole(CUSTOMER) {
        Order storage order = orders[_orderId];
        require(order.createdAt > 0, "Order not found");
        require(order.status == OrderStatus.PENDING, "Order already processed");

        // Restore stock
        string memory sku = order.sku;
        inventory[sku] += order.quantity;
        products[sku].stock += order.quantity;
        emit StockUpdated(sku, inventory[sku]);

        order.status = OrderStatus.CANCELED;
        order.updatedAt = block.timestamp;

        emit OrderCanceled(_orderId);
    }

    /**
     * @notice Processes payment for an order
     * @param _orderId The unique ID of the order
     * @param _amount The amount to pay in tokens
     * @dev Only CUSTOMER role can call this function
     */
    function processPayment(bytes32 _orderId, uint256 _amount) public onlyRole(CUSTOMER) {
        Order storage order = orders[_orderId];
        require(order.createdAt > 0, "Order not found");
        require(order.status == OrderStatus.PENDING, "Order already processed");
        require(_amount > 0, "Amount must be greater than zero");

        // Calculate total price
        uint256 totalPrice = products[order.sku].price * order.quantity;
        require(_amount >= totalPrice, "Amount is less than order total");

        // Transfer tokens from customer to company
        token.transferFrom(msg.sender, address(this), _amount);

        // Store payment information
        bytes32 paymentId = keccak256(abi.encodePacked(block.timestamp, msg.sender, _orderId));
        payments[paymentId] = Payment(_orderId, _amount, block.timestamp);
        allPaymentIds.push(paymentId);

        emit PaymentReceived(paymentId, _amount);
    }

    /**
     * @notice Refunds payment for a canceled order
     * @param _paymentId The unique ID of the payment
     * @dev Only COMPANY role can call this function
     */
    function refundPayment(bytes32 _paymentId) public onlyRole(COMPANY) {
        Payment storage payment = payments[_paymentId];
        require(payment.timestamp > 0, "Payment not found");

        // Get order information
        Order storage order = orders[payment.orderId];
        require(order.status == OrderStatus.CANCELED, "Order not canceled");

        // Refund tokens to customer
        token.transfer(order.customer, payment.amount);

        emit PaymentRefunded(_paymentId, payment.amount);
    }

    /**
     * @notice Grants roles to new users
     * @param _user The address of the user
     * @param _role The role to grant
     * @dev Only ADMIN role can call this function
     */
    function grantRole(address _user, bytes32 _role) public onlyRole(ADMIN) {
        _grantRole(_role, _user);
    }

    /**
     * @notice Revokes roles from users
     * @param _user The address of the user
     * @param _role The role to revoke
     * @dev Only ADMIN role can call this function
     */
    function revokeRole(address _user, bytes32 _role) public onlyRole(ADMIN) {
        _revokeRole(_user, _role);
    }

    modifier onlyRole(bytes32 _role) {
        require(hasRole(_role, msg.sender), "Access denied");
        _;
    }
}
